-- Complaints, cases and investigations
create table if not exists public.complaints (id uuid primary key default gen_random_uuid(), complaint_number text not null unique, received_at timestamptz not null default now(), channel text, category text, status text not null default 'received', summary text not null, due_at timestamptz, responsible_officer_id uuid references public.profiles(id), government_body_id uuid references public.government_bodies(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.cases (id uuid primary key default gen_random_uuid(), case_number text not null unique, complaint_id uuid references public.complaints(id), case_type text not null, status text not null, responsible_officer_id uuid references public.profiles(id), due_at timestamptz, closed_at timestamptz, classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.complaint_parties (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.complaint_documents (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.screening_assessments (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.screening_decisions (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.case_assignments (id uuid primary key default gen_random_uuid(), case_ref uuid not null references public.cases(id) on delete cascade, user_id uuid not null references public.profiles(id), assignment_role text, assigned_at timestamptz not null default now(), ended_at timestamptz, classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(case_ref,user_id,assignment_role));
create table if not exists public.case_parties (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.case_events (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.case_tasks (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.case_extensions (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.allegations (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.investigations (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.investigation_plans (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.investigation_plan_steps (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.evidence_items (id uuid primary key default gen_random_uuid(), evidence_number text not null unique, case_ref uuid not null references public.cases(id) on delete cascade, evidence_type text, source text, received_at timestamptz, received_by uuid references public.profiles(id), description text, storage_object_key text, file_hash text, current_custodian uuid references public.profiles(id), legal_hold boolean not null default false, classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.evidence_custody_events (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.interviews (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.interview_participants (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.statutory_notices (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.information_requests (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.responses (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.findings (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.right_to_be_heard_notices (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.right_to_be_heard_responses (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.closure_decisions (id uuid primary key default gen_random_uuid(), case_ref uuid references public.cases(id), classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.complaints add constraint complaints_case_id_fk foreign key (case_id) references public.cases(id) deferrable initially deferred;
